#include "gpi/inductive_synthesis.hpp"
#include "gpi/filesystem_safety.hpp"
#include "gpi/foreign_project_intelligence.hpp"

#include <algorithm>
#include <cctype>
#include <fstream>
#include <set>
#include <stdexcept>

namespace genomic::gpi { namespace {
std::string read(const std::filesystem::path& p){std::ifstream in(p,std::ios::binary);if(!in)throw std::runtime_error("Cannot read "+p.string());return {std::istreambuf_iterator<char>(in),{}};}
void write(const std::filesystem::path& p,const std::string& s){std::filesystem::create_directories(p.parent_path());std::ofstream out(p,std::ios::binary|std::ios::trunc);if(!out)throw std::runtime_error("Cannot write "+p.string());out<<s;}
bool cpp(const std::filesystem::path& p){const auto e=p.extension().string();return e==".cpp"||e==".cc"||e==".cxx";}
void copyTree(const std::filesystem::path& from,const std::filesystem::path& to){std::error_code ec;std::filesystem::create_directories(to);for(const auto& item:std::filesystem::recursive_directory_iterator(from)){if(item.is_symlink())throw std::runtime_error("Symlink in protected project");const auto out=to/std::filesystem::relative(item.path(),from);if(item.is_directory())std::filesystem::create_directories(out);else if(item.is_regular_file()){std::filesystem::create_directories(out.parent_path());std::filesystem::copy_file(item.path(),out,std::filesystem::copy_options::overwrite_existing,ec);if(ec)throw std::runtime_error("Cannot copy candidate");}}}
std::size_t openingParen(const std::string& text,std::size_t close){int depth=0;for(std::size_t i=close+1;i-->0;){if(text[i]==')')++depth;else if(text[i]=='('&&--depth==0)return i;}return std::string::npos;}
std::vector<std::string> identifiers(const std::string& params){std::vector<std::string> result;std::size_t begin=0;while(begin<params.size()){const auto end=params.find(',',begin);const auto part=params.substr(begin,end==std::string::npos?end:end-begin);std::size_t i=part.size();while(i>0&&!std::isalnum(static_cast<unsigned char>(part[i-1]))&&part[i-1]!='_')--i;const auto stop=i;while(i>0&&(std::isalnum(static_cast<unsigned char>(part[i-1]))||part[i-1]=='_'))--i;if(stop>i&&part.substr(i,stop-i)!="void")result.push_back(part.substr(i,stop-i));if(end==std::string::npos)break;begin=end+1;}return result;}
std::vector<int> constants(const std::filesystem::path& root){std::set<int> values{0,1};for(const auto& item:std::filesystem::recursive_directory_iterator(root)){if(!item.is_regular_file()||!cpp(item.path()))continue;const auto text=read(item.path());for(std::size_t i=0;i<text.size();){if(!std::isdigit(static_cast<unsigned char>(text[i]))){++i;continue;}int v=0;while(i<text.size()&&std::isdigit(static_cast<unsigned char>(text[i]))){v=v*10+(text[i]-'0');++i;}if(v>=0&&v<=16)values.insert(v);}}return {values.begin(),values.end()};}
struct Stub {std::filesystem::path path;std::size_t returnBegin{},returnEnd{};std::vector<std::string> args;};
std::vector<Stub> stubs(const std::filesystem::path& root){std::vector<Stub> result;for(const auto& item:std::filesystem::recursive_directory_iterator(root)){if(!item.is_regular_file()||!cpp(item.path()))continue;const auto text=read(item.path());std::size_t p=0;while((p=text.find("return 0;",p))!=std::string::npos){const auto brace=text.rfind('{',p);const auto close=text.rfind(')',brace);const auto open=close==std::string::npos?std::string::npos:openingParen(text,close);if(brace!=std::string::npos&&open!=std::string::npos&&text.substr(open,brace-open).find("main")==std::string::npos){auto args=identifiers(text.substr(open+1,close-open-1));if(!args.empty())result.push_back({item.path(),p,p+9,std::move(args)});}p+=9;}}return result;}
bool known(const std::filesystem::path& p){return !p.empty()&&std::filesystem::exists(p)&&read(p).find("GDIIS1|success|expression_synthesis")!=std::string::npos;}
void memory(const std::filesystem::path& p,const std::string& status,const std::string& value){if(p.empty())return;std::filesystem::create_directories(p.parent_path());std::ofstream out(p,std::ios::binary|std::ios::app);if(!out)throw std::runtime_error("Cannot persist synthesis experience");out<<"GDIIS1|"<<status<<"|expression_synthesis|"<<value<<'\n';}
void report(const InductiveSynthesisConfig& c,InductiveSynthesisResult& r){r.reportPath=c.isolatedWorkspace/"inductive_synthesis.json";std::ofstream out(r.reportPath);out<<"{\n\"format\":\"GDIIS1\",\n\"outcome\":\""<<toString(r.outcome)<<"\",\n\"attempts\":"<<r.attempts.size()<<",\n\"original_untouched\":"<<(r.originalUntouched?"true":"false")<<"\n}\n";}
}
const char* toString(const InductiveSynthesisOutcome v) noexcept {switch(v){case InductiveSynthesisOutcome::Complete:return "COMPLETE";case InductiveSynthesisOutcome::AlreadySatisfied:return "ALREADY_SATISFIED";case InductiveSynthesisOutcome::Blocked:return "BLOCKED";case InductiveSynthesisOutcome::Failed:return "FAILED";}return "FAILED";}
InductiveSynthesisResult runInductiveSynthesis(const InductiveSynthesisConfig& c){if(c.protectedProject.empty()||c.isolatedWorkspace.empty()||c.maxCandidates==0||c.maxCandidates>50)throw std::invalid_argument("Inductive synthesis requires 1..50 candidates");InductiveSynthesisResult r;const auto root=std::filesystem::absolute(c.protectedProject),work=std::filesystem::absolute(c.isolatedWorkspace);const auto before=computeDirectoryTreeHash(root);try{validateIsolatedWorkspace(root,work);const auto contract=discoverBuildContract(root);NativeBuildConfig base=c.nativeBuild;base.originalProject=root;base.isolatedWorkspace=work/"baseline";r.baseline=executeNativeBuild(contract,base);if(r.baseline.built&&r.baseline.testsPassed){r.outcome=InductiveSynthesisOutcome::AlreadySatisfied;r.reason="baseline_tests_already_satisfied";}else if(!r.baseline.built){r.outcome=InductiveSynthesisOutcome::Blocked;r.reason="baseline_does_not_compile";}else{r.experienceUsed=known(c.experienceStore);const auto values=constants(root);std::size_t n=0;for(const auto& stub:stubs(root)){std::vector<std::string> expressions;for(const auto& argument:stub.args)expressions.push_back(argument);for(const auto& left:stub.args)for(const auto& right:stub.args)if(left!=right)for(const auto k:values){const auto additive=left+" + "+right+" * "+std::to_string(k);const auto multiplicative=left+" * "+std::to_string(k)+" + "+right;if(r.experienceUsed){expressions.push_back(additive);expressions.push_back(multiplicative);}else{expressions.push_back(multiplicative);expressions.push_back(additive);}}for(const auto& left:stub.args)for(const auto k:values){expressions.push_back(left+" + "+left+" * "+std::to_string(k));expressions.push_back(left+" * "+std::to_string(k)+" + "+left);}for(const auto& expression:expressions){if(++n>c.maxCandidates)break;const auto candidate=work/("candidate_"+std::to_string(n));copyTree(root,candidate);const auto relative=std::filesystem::relative(stub.path,root);auto text=read(candidate/relative);text.replace(stub.returnBegin,stub.returnEnd-stub.returnBegin,"return "+expression+";");write(candidate/relative,text);const auto cc=discoverBuildContract(candidate);NativeBuildConfig build=c.nativeBuild;build.originalProject=candidate;build.isolatedWorkspace=work/("candidate_build_"+std::to_string(n));const auto evidence=executeNativeBuild(cc,build);r.attempts.push_back({relative,expression,evidence.built,evidence.testsPassed});if(evidence.built&&evidence.testsPassed){r.developedProject=candidate;r.outcome=InductiveSynthesisOutcome::Complete;r.reason="counterexample_guided_expression_verified";memory(c.experienceStore,"success",expression);r.experiencePersisted=!c.experienceStore.empty();goto done;}memory(c.experienceStore,"failed",expression);}if(n>=c.maxCandidates)break;}if(r.outcome!=InductiveSynthesisOutcome::Complete){r.outcome=InductiveSynthesisOutcome::Blocked;r.reason="expression_grammar_exhausted";}}}catch(const std::exception& e){r.outcome=InductiveSynthesisOutcome::Failed;r.reason=e.what();}done:r.originalUntouched=before==computeDirectoryTreeHash(root);report(c,r);return r;}
} // namespace genomic::gpi
